=== FILE: sync_fifo.v ===
`timescale 1ns/1ps
// sync_fifo: parameterizable single-clock FIFO with first-word fall-through.
// Implements interface_spec.md per microarchitecture.md (explicit count
// register, pointers wrapping at LAST, flags gate the requests).
module sync_fifo #(
    parameter integer DEPTH = 8,
    parameter integer WIDTH = 8
) (
    input  wire                       clk,
    input  wire                       rst_n,
    input  wire                       wr_en,
    input  wire [WIDTH-1:0]           wr_data,
    output wire                       full,
    input  wire                       rd_en,
    output wire [WIDTH-1:0]           rd_data,
    output wire                       empty,
    output wire [$clog2(DEPTH+1)-1:0] count
);

    localparam integer AW = $clog2(DEPTH);
    localparam integer CW = $clog2(DEPTH+1);
    localparam [31:0] LAST32  = DEPTH - 1;
    localparam [31:0] DEPTH32 = DEPTH;
    localparam [31:0] ONE32   = 32'd1;

    reg [WIDTH-1:0] mem [0:DEPTH-1];

    reg [AW-1:0] wr_ptr_q;
    reg [AW-1:0] wr_ptr_d;
    reg [AW-1:0] rd_ptr_q;
    reg [AW-1:0] rd_ptr_d;
    reg [CW-1:0] count_q;
    reg [CW-1:0] count_d;

    assign full    = (count_q == DEPTH32[CW-1:0]);
    assign empty   = (count_q == {CW{1'b0}});
    assign count   = count_q;
    assign rd_data = mem[rd_ptr_q];

    wire wr_acc = wr_en & ~full;
    wire rd_acc = rd_en & ~empty;

    // Next-state logic.
    always @* begin
        wr_ptr_d = wr_ptr_q;
        rd_ptr_d = rd_ptr_q;
        count_d  = count_q;
        if (wr_acc) begin
            if (wr_ptr_q == LAST32[AW-1:0])
                wr_ptr_d = {AW{1'b0}};
            else
                wr_ptr_d = wr_ptr_q + ONE32[AW-1:0];
        end
        if (rd_acc) begin
            if (rd_ptr_q == LAST32[AW-1:0])
                rd_ptr_d = {AW{1'b0}};
            else
                rd_ptr_d = rd_ptr_q + ONE32[AW-1:0];
        end
        if (wr_acc && !rd_acc)
            count_d = count_q + ONE32[CW-1:0];
        else if (rd_acc && !wr_acc)
            count_d = count_q - ONE32[CW-1:0];
    end

    // Control registers: synchronous active-low reset.
    always @(posedge clk) begin
        if (!rst_n) begin
            wr_ptr_q <= {AW{1'b0}};
            rd_ptr_q <= {AW{1'b0}};
            count_q  <= {CW{1'b0}};
        end else begin
            wr_ptr_q <= wr_ptr_d;
            rd_ptr_q <= rd_ptr_d;
            count_q  <= count_d;
        end
    end

    // Storage: datapath, not reset, written only outside reset.
    always @(posedge clk) begin
        if (rst_n && wr_acc)
            mem[wr_ptr_q] <= wr_data;
    end

`ifdef FORMAL
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk)
        f_past_valid <= 1'b1;

    always @(*)
        if (!f_past_valid)
            assume(!rst_n);

    (* anyconst *) reg [AW-1:0] f_addr;
    always @(*)
        assume(f_addr <= LAST32[AW-1:0]);

    wire [31:0] f_sum  = rd_ptr_q + count_q;
    wire [31:0] f_wexp = (f_sum >= DEPTH32) ? (f_sum - DEPTH32) : f_sum;
    wire [31:0] f_dist = (f_addr >= rd_ptr_q) ? (f_addr - rd_ptr_q)
                                              : (f_addr + DEPTH32 - rd_ptr_q);
    wire        f_inuse = (f_dist < count_q);

    reg [WIDTH-1:0] f_data;
    always @(posedge clk)
        if (rst_n && wr_acc && (wr_ptr_q == f_addr))
            f_data <= wr_data;

    reg f_was_full;
    initial f_was_full = 1'b0;
    always @(posedge clk)
        if (!rst_n)
            f_was_full <= 1'b0;
        else if (full)
            f_was_full <= 1'b1;

    // State invariants.
    always @(*) begin
        if (f_past_valid) begin
            assert(count_q <= DEPTH32[CW-1:0]);
            assert(wr_ptr_q <= LAST32[AW-1:0]);
            assert(rd_ptr_q <= LAST32[AW-1:0]);
            assert(full == (count_q == DEPTH32[CW-1:0]));
            assert(empty == (count_q == {CW{1'b0}}));
            assert(!(full && empty));
            assert(f_wexp == wr_ptr_q);
            if (f_inuse)
                assert(mem[f_addr] == f_data);
            if (f_inuse && (rd_ptr_q == f_addr))
                assert(rd_data == f_data);
        end
    end

    // Step properties.
    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n)) begin
                assert(count_q == {CW{1'b0}});
                assert(wr_ptr_q == {AW{1'b0}});
                assert(rd_ptr_q == {AW{1'b0}});
                assert(empty);
                assert(!full);
            end else begin
                if ($past(wr_acc) && !$past(rd_acc))
                    assert(count_q == $past(count_q) + ONE32[CW-1:0]);
                else if (!$past(wr_acc) && $past(rd_acc))
                    assert(count_q == $past(count_q) - ONE32[CW-1:0]);
                else
                    assert(count_q == $past(count_q));

                if ($past(wr_acc))
                    assert(wr_ptr_q == (($past(wr_ptr_q) == LAST32[AW-1:0]) ?
                                        {AW{1'b0}} : $past(wr_ptr_q) + ONE32[AW-1:0]));
                else
                    assert(wr_ptr_q == $past(wr_ptr_q));

                if ($past(rd_acc))
                    assert(rd_ptr_q == (($past(rd_ptr_q) == LAST32[AW-1:0]) ?
                                        {AW{1'b0}} : $past(rd_ptr_q) + ONE32[AW-1:0]));
                else
                    assert(rd_ptr_q == $past(rd_ptr_q));

                if ($past(wr_en && full))
                    assert(wr_ptr_q == $past(wr_ptr_q));
                if ($past(wr_en && full && !rd_en)) begin
                    assert(full);
                    assert(count_q == $past(count_q));
                end
                if ($past(rd_en && empty))
                    assert(rd_ptr_q == $past(rd_ptr_q));
                if ($past(rd_en && empty && !wr_en)) begin
                    assert(empty);
                    assert(count_q == $past(count_q));
                end
            end
        end
    end

    // Covers.
    always @(posedge clk) begin
        if (f_past_valid && rst_n) begin
            cover(full);
            cover(wr_en && full);
            cover(f_was_full && empty);
            cover(rd_acc && f_inuse && (rd_ptr_q == f_addr));
        end
    end
`endif

endmodule
=== END FILE ===
