`timescale 1ns/1ps
// Self-checking testbench for sync_fifo: two instances (DEPTH 8 x WIDTH 8,
// DEPTH 5 x WIDTH 12) on the same stimulus, each with a reference queue
// checked every cycle, plus coverage counters for the spec's corner cases.
module sync_fifo_tb;

    localparam integer DA = 8;
    localparam integer WA = 8;
    localparam integer DB = 5;
    localparam integer WB = 12;
    localparam integer CA = $clog2(DA+1);
    localparam integer CB = $clog2(DB+1);

    reg clk;
    initial clk = 1'b0;
    always #5 clk = ~clk;

    reg          rst_n;
    reg          wr_en;
    reg          rd_en;
    reg [WB-1:0] wdata;

    wire          fullA;
    wire          emptyA;
    wire [WA-1:0] rdA;
    wire [CA-1:0] cntA;
    wire          fullB;
    wire          emptyB;
    wire [WB-1:0] rdB;
    wire [CB-1:0] cntB;

    sync_fifo #(.DEPTH(DA), .WIDTH(WA)) dutA (
        .clk(clk), .rst_n(rst_n), .wr_en(wr_en), .wr_data(wdata[WA-1:0]),
        .full(fullA), .rd_en(rd_en), .rd_data(rdA), .empty(emptyA), .count(cntA)
    );

    sync_fifo #(.DEPTH(DB), .WIDTH(WB)) dutB (
        .clk(clk), .rst_n(rst_n), .wr_en(wr_en), .wr_data(wdata),
        .full(fullB), .rd_en(rd_en), .rd_data(rdB), .empty(emptyB), .count(cntB)
    );

    // Reference queues.
    reg [WA-1:0] qA [0:7];
    reg [2:0]    hA;
    reg [2:0]    tA;
    reg [3:0]    nA;
    reg [WB-1:0] qB [0:4];
    reg [2:0]    hB;
    reg [2:0]    tB;
    reg [2:0]    nB;

    integer passed;
    integer failed;
    integer cyc;
    integer i;
    integer nonce_ok;
    reg [8*64-1:0] nonce;
    reg [31:0] rnd;
    reg [11:0] dval;
    reg [3:0]  wbias;
    reg [3:0]  rbias;

    // Coverage counters.
    integer covA_wrfull, covA_rdempty, covA_bothempty, covA_bothfull, covA_bothmid;
    integer covA_fill, covA_drain, covA_wwrap, covA_rwrap, covA_rst;
    integer covB_wrfull, covB_rdempty, covB_bothempty, covB_bothfull, covB_bothmid;
    integer covB_fill, covB_drain, covB_wwrap, covB_rwrap, covB_rst;

    task chk;
        input       ok;
        input [7:0] id;
        begin
            if (ok) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("sync_fifo_tb: check %0d failed at cycle %0d", id, cyc);
            end
        end
    endtask

    task model_edge;
        reg wa;
        reg ra;
        begin
            if (!rst_n) begin
                if (nA != 4'd0) covA_rst = covA_rst + 1;
                if (nB != 3'd0) covB_rst = covB_rst + 1;
                hA = 3'd0; tA = 3'd0; nA = 4'd0;
                hB = 3'd0; tB = 3'd0; nB = 3'd0;
            end else begin
                // Instance A, depth 8.
                wa = wr_en && (nA != 4'd8);
                ra = rd_en && (nA != 4'd0);
                if (wr_en && (nA == 4'd8)) covA_wrfull = covA_wrfull + 1;
                if (rd_en && (nA == 4'd0)) covA_rdempty = covA_rdempty + 1;
                if (wr_en && rd_en && (nA == 4'd0)) covA_bothempty = covA_bothempty + 1;
                if (wr_en && rd_en && (nA == 4'd8)) covA_bothfull = covA_bothfull + 1;
                if (wr_en && rd_en && (nA != 4'd0) && (nA != 4'd8)) covA_bothmid = covA_bothmid + 1;
                if (wa && !ra && (nA == 4'd7)) covA_fill = covA_fill + 1;
                if (ra && !wa && (nA == 4'd1)) covA_drain = covA_drain + 1;
                if (wa && (tA == 3'd7)) covA_wwrap = covA_wwrap + 1;
                if (ra && (hA == 3'd7)) covA_rwrap = covA_rwrap + 1;
                if (wa) begin
                    qA[tA] = wdata[WA-1:0];
                    tA = (tA == 3'd7) ? 3'd0 : tA + 3'd1;
                end
                if (ra)
                    hA = (hA == 3'd7) ? 3'd0 : hA + 3'd1;
                if (wa && !ra)
                    nA = nA + 4'd1;
                else if (ra && !wa)
                    nA = nA - 4'd1;

                // Instance B, depth 5.
                wa = wr_en && (nB != 3'd5);
                ra = rd_en && (nB != 3'd0);
                if (wr_en && (nB == 3'd5)) covB_wrfull = covB_wrfull + 1;
                if (rd_en && (nB == 3'd0)) covB_rdempty = covB_rdempty + 1;
                if (wr_en && rd_en && (nB == 3'd0)) covB_bothempty = covB_bothempty + 1;
                if (wr_en && rd_en && (nB == 3'd5)) covB_bothfull = covB_bothfull + 1;
                if (wr_en && rd_en && (nB != 3'd0) && (nB != 3'd5)) covB_bothmid = covB_bothmid + 1;
                if (wa && !ra && (nB == 3'd4)) covB_fill = covB_fill + 1;
                if (ra && !wa && (nB == 3'd1)) covB_drain = covB_drain + 1;
                if (wa && (tB == 3'd4)) covB_wwrap = covB_wwrap + 1;
                if (ra && (hB == 3'd4)) covB_rwrap = covB_rwrap + 1;
                if (wa) begin
                    qB[tB] = wdata;
                    tB = (tB == 3'd4) ? 3'd0 : tB + 3'd1;
                end
                if (ra)
                    hB = (hB == 3'd4) ? 3'd0 : hB + 3'd1;
                if (wa && !ra)
                    nB = nB + 3'd1;
                else if (ra && !wa)
                    nB = nB - 3'd1;
            end
        end
    endtask

    task check_all;
        begin
            chk(fullA == (nA == 4'd8), 8'd1);
            chk(emptyA == (nA == 4'd0), 8'd2);
            chk(cntA == nA, 8'd3);
            if (nA != 4'd0)
                chk(rdA == qA[hA], 8'd4);
            chk(fullB == (nB == 3'd5), 8'd11);
            chk(emptyB == (nB == 3'd0), 8'd12);
            chk(cntB == nB, 8'd13);
            if (nB != 3'd0)
                chk(rdB == qB[hB], 8'd14);
        end
    endtask

    task cycle;
        begin
            @(posedge clk);
            model_edge;
            @(negedge clk);
            cyc = cyc + 1;
            check_all;
        end
    endtask

    task drive;
        input        i_rst_n;
        input        i_wr;
        input        i_rd;
        input [11:0] i_data;
        begin
            rst_n = i_rst_n;
            wr_en = i_wr;
            rd_en = i_rd;
            wdata = i_data;
            cycle;
        end
    endtask

    initial begin
        passed = 0; failed = 0; cyc = 0;
        hA = 3'd0; tA = 3'd0; nA = 4'd0;
        hB = 3'd0; tB = 3'd0; nB = 3'd0;
        covA_wrfull = 0; covA_rdempty = 0; covA_bothempty = 0; covA_bothfull = 0; covA_bothmid = 0;
        covA_fill = 0; covA_drain = 0; covA_wwrap = 0; covA_rwrap = 0; covA_rst = 0;
        covB_wrfull = 0; covB_rdempty = 0; covB_bothempty = 0; covB_bothfull = 0; covB_bothmid = 0;
        covB_fill = 0; covB_drain = 0; covB_wwrap = 0; covB_rwrap = 0; covB_rst = 0;
        rst_n = 1'b0; wr_en = 1'b0; rd_en = 1'b0; wdata = 12'd0;
        dval = 12'h0A0;
        rnd = 32'd0;
        wbias = 4'd8; rbias = 4'd8;

        // Reset with requests asserted: they must be ignored.
        for (i = 0; i < 3; i = i + 1)
            drive(1'b0, 1'b1, 1'b1, dval);

        // Fill to full, then write while full.
        for (i = 0; i < 10; i = i + 1) begin
            drive(1'b1, 1'b1, 1'b0, dval);
            dval = dval + 12'd1;
        end

        // Write and read together: when full, then in between.
        for (i = 0; i < 3; i = i + 1) begin
            drive(1'b1, 1'b1, 1'b1, dval);
            dval = dval + 12'd1;
        end

        // Drain to empty, then read while empty.
        for (i = 0; i < 12; i = i + 1)
            drive(1'b1, 1'b0, 1'b1, dval);

        // Write and read together when empty.
        for (i = 0; i < 2; i = i + 1) begin
            drive(1'b1, 1'b1, 1'b1, dval);
            dval = dval + 12'd1;
        end
        for (i = 0; i < 2; i = i + 1)
            drive(1'b1, 1'b0, 1'b1, dval);

        // Reset during traffic.
        for (i = 0; i < 3; i = i + 1) begin
            drive(1'b1, 1'b1, 1'b0, dval);
            dval = dval + 12'd1;
        end
        drive(1'b0, 1'b1, 1'b1, dval);
        drive(1'b1, 1'b0, 1'b1, dval);

        // Random traffic in four bias phases, with rare resets.
        for (i = 0; i < 2000; i = i + 1) begin
            if (i == 0)    begin wbias = 4'd12; rbias = 4'd4;  end
            if (i == 500)  begin wbias = 4'd4;  rbias = 4'd12; end
            if (i == 1000) begin wbias = 4'd8;  rbias = 4'd8;  end
            if (i == 1500) begin wbias = 4'd14; rbias = 4'd14; end
            rnd = $random;
            drive((rnd[31:24] != 8'd0) ? 1'b1 : 1'b0,
                  (rnd[3:0] < wbias) ? 1'b1 : 1'b0,
                  (rnd[7:4] < rbias) ? 1'b1 : 1'b0,
                  rnd[19:8]);
        end

        // Final drain.
        for (i = 0; i < 10; i = i + 1)
            drive(1'b1, 1'b0, 1'b1, dval);

        // Coverage goals.
        chk(covA_wrfull    != 0, 8'd30);
        chk(covA_rdempty   != 0, 8'd31);
        chk(covA_bothempty != 0, 8'd32);
        chk(covA_bothfull  != 0, 8'd33);
        chk(covA_bothmid   != 0, 8'd34);
        chk(covA_fill      != 0, 8'd35);
        chk(covA_drain     != 0, 8'd36);
        chk(covA_wwrap     != 0, 8'd37);
        chk(covA_rwrap     != 0, 8'd38);
        chk(covA_rst       != 0, 8'd39);
        chk(covB_wrfull    != 0, 8'd40);
        chk(covB_rdempty   != 0, 8'd41);
        chk(covB_bothempty != 0, 8'd42);
        chk(covB_bothfull  != 0, 8'd43);
        chk(covB_bothmid   != 0, 8'd44);
        chk(covB_fill      != 0, 8'd45);
        chk(covB_drain     != 0, 8'd46);
        chk(covB_wwrap     != 0, 8'd47);
        chk(covB_rwrap     != 0, 8'd48);
        chk(covB_rst       != 0, 8'd49);

        nonce = {(8*64){1'b0}};
        nonce_ok = $value$plusargs("nirmaan_nonce=%s", nonce);
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule
